20	/* global document */
21	
22	import * as echarts from '../../../core/echarts';
23	import * as zrUtil from 'zrender/src/core/util';
24	import GlobalModel from '../../../model/Global';
25	import SeriesModel from '../../../model/Series';
26	import { ToolboxFeature, ToolboxFeatureOption } from '../featureManager';
27	import { ColorString, ECUnitOption, SeriesOption, Payload, Dictionary } from '../../../util/types';
28	import ExtensionAPI from '../../../core/ExtensionAPI';
29	import { addEventListener } from 'zrender/src/core/event';
30	import Axis from '../../../coord/Axis';
31	import Cartesian2D from '../../../coord/cartesian/Cartesian2D';
