35	/* global document */
36	
37	const BLOCK_SPLITER = new Array(60).join('-');
38	const ITEM_SPLITER = '\t';
39	
40	type DataItem = {
41	    name: string
42	    value: number[] | number
43	};
44	
45	type DataList = (DataItem | number | number[])[];
46	
47	interface ChangeDataViewPayload extends Payload {
48	    newOption: {
49	        series: SeriesOption[]
50	    }
51	}
52	
53	interface SeriesGroupMeta {
54	    axisDim: string
55	    axisIndex: number
56	}
57	
58	interface SeriesGroup {
59	    series: SeriesModel[]
60	    categoryAxis: Axis
61	    valueAxis: Axis
62	}
63	
64	/**
65	 * Group series into two types
66	 *  1. on category axis, like line, bar
67	 *  2. others, like scatter, pie
68	 */
69	function groupSeries(ecModel: GlobalModel) {
70	    const seriesGroupByCategoryAxis: Dictionary<SeriesGroup> = {};
71	    const otherSeries: SeriesModel[] = [];
72	    const meta: SeriesGroupMeta[] = [];
73	    ecModel.eachRawSeries(function (seriesModel) {
74	        const coordSys = seriesModel.coordinateSystem;
75	
76	        if (coordSys && (coordSys.type === 'cartesian2d' || coordSys.type === 'polar')) {
77	            // TODO: TYPE Consider polar? Include polar may increase unecessary bundle size.
78	            const baseAxis = (coordSys as Cartesian2D).getBaseAxis();
79	            if (baseAxis.type === 'category') {
80	                const key = baseAxis.dim + '_' + baseAxis.index;
81	                if (!seriesGroupByCategoryAxis[key]) {
82	                    seriesGroupByCategoryAxis[key] = {
83	                        categoryAxis: baseAxis,
84	                        valueAxis: coordSys.getOtherAxis(baseAxis),
85	                        series: []
86	                    };
87	                    meta.push({
88	                        axisDim: baseAxis.dim,
89	                        axisIndex: baseAxis.index
90	                    });
91	                }
92	                seriesGroupByCategoryAxis[key].series.push(seriesModel);
93	            }
94	            else {
95	                otherSeries.push(seriesModel);
96	            }
97	        }
98	        else {
99	            otherSeries.push(seriesModel);
100	        }
101	    });
102	
103	    return {
104	        seriesGroupByCategoryAxis: seriesGroupByCategoryAxis,
105	        other: otherSeries,
106	        meta: meta
107	    };
108	}
109	
110	/**
111	 * Assemble content of series on cateogory axis
112	 * @inner
113	 */
114	function assembleSeriesWithCategoryAxis(groups: Dictionary<SeriesGroup>): string {
115	    const tables: string[] = [];
116	    zrUtil.each(groups, function (group, key) {
117	        const categoryAxis = group.categoryAxis;
118	        const valueAxis = group.valueAxis;
119	        const valueAxisDim = valueAxis.dim;
120	
121	        const headers = [' '].concat(zrUtil.map(group.series, function (series) {
122	            return series.name;
123	        }));
124	        // @ts-ignore TODO Polar
125	        const columns = [categoryAxis.model.getCategories()];
126	        zrUtil.each(group.series, function (series) {
127	            const rawData = series.getRawData();
128	            columns.push(series.getRawData().mapArray(rawData.mapDimension(valueAxisDim), function (val) {
129	                return val;
130	            }));
131	        });
132	        // Assemble table content
133	        const lines = [headers.join(ITEM_SPLITER)];
134	        for (let i = 0; i < columns[0].length; i++) {
135	            const items = [];
136	            for (let j = 0; j < columns.length; j++) {
137	                items.push(columns[j][i]);
138	            }
139	            lines.push(items.join(ITEM_SPLITER));
140	        }
141	        tables.push(lines.join('\n'));
142	    });
143	    return tables.join('\n\n' + BLOCK_SPLITER + '\n\n');
144	}
145	
146	/**
147	 * Assemble content of other series
148	 */
149	function assembleOtherSeries(series: SeriesModel[]) {
150	    return zrUtil.map(series, function (series) {
151	        const data = series.getRawData();
152	        const lines = [series.name];
153	        const vals: string[] = [];
154	        data.each(data.dimensions, function () {
155	            const argLen = arguments.length;
156	            const dataIndex = arguments[argLen - 1];
157	            const name = data.getName(dataIndex);
158	            for (let i = 0; i < argLen - 1; i++) {
159	                vals[i] = arguments[i];
160	            }
161	            lines.push((name ? (name + ITEM_SPLITER) : '') + vals.join(ITEM_SPLITER));
162	        });
163	        return lines.join('\n');
164	    }).join('\n\n' + BLOCK_SPLITER + '\n\n');
165	}
166	
167	function getContentFromModel(ecModel: GlobalModel) {
168	
169	    const result = groupSeries(ecModel);
170	
171	    return {
172	        value: zrUtil.filter([
173	                assembleSeriesWithCategoryAxis(result.seriesGroupByCategoryAxis),
174	                assembleOtherSeries(result.other)
175	            ], function (str) {
176	                return !!str.replace(/[\n\t\s]/g, '');
177	            }).join('\n\n' + BLOCK_SPLITER + '\n\n'),
178	
179	        meta: result.meta
180	    };
181	}
182	
183	
184	function trim(str: string) {
185	    return str.replace(/^\s\s*/, '').replace(/\s\s*$/, '');
186	}
187	/**
188	 * If a block is tsv format
189	 */
190	function isTSVFormat(block: string): boolean {
191	    // Simple method to find out if a block is tsv format
192	    const firstLine = block.slice(0, block.indexOf('\n'));
193	    if (firstLine.indexOf(ITEM_SPLITER) >= 0) {
194	        return true;
195	    }
196	}
197	
198	const itemSplitRegex = new RegExp('[' + ITEM_SPLITER + ']+', 'g');
199	/**
200	 * @param {string} tsv
201	 * @return {Object}
202	 */
203	function parseTSVContents(tsv: string) {
204	    const tsvLines = tsv.split(/\n+/g);
205	    const headers = trim(tsvLines.shift()).split(itemSplitRegex);
206	
207	    const categories: string[] = [];
208	    const series: {name: string, data: string[]}[] = zrUtil.map(headers, function (header) {
209	        return {
210	            name: header,
211	            data: []
212	        };
213	    });
214	    for (let i = 0; i < tsvLines.length; i++) {
215	        const items = trim(tsvLines[i]).split(itemSplitRegex);
216	        categories.push(items.shift());
217	        for (let j = 0; j < items.length; j++) {
218	            series[j] && (series[j].data[i] = items[j]);
219	        }
220	    }
221	    return {
222	        series: series,
223	        categories: categories
224	    };
225	}
226	
227	function parseListContents(str: string) {
228	    const lines = str.split(/\n+/g);
229	    const seriesName = trim(lines.shift());
230	
231	    const data: DataList = [];
232	    for (let i = 0; i < lines.length; i++) {
233	        // if line is empty, ignore it.
234	        // there is a case that a user forgot to delete `\n`.
235	        const line = trim(lines[i]);
236	        if (!line) {
237	            continue;
238	        }
239	        let items = line.split(itemSplitRegex);
240	
241	        let name = '';
242	        let value: number[];
243	        let hasName = false;
244	        if (isNaN(items[0] as unknown as number)) { // First item is name
245	            hasName = true;
246	            name = items[0];
247	            items = items.slice(1);
248	            data[i] = {
249	                name: name,
250	                value: []
251	            };
252	            value = (data[i] as DataItem).value as number[];
253	        }
254	        else {
255	            value = data[i] = [];
256	        }
257	        for (let j = 0; j < items.length; j++) {
258	            value.push(+items[j]);
259	        }
260	        if (value.length === 1) {
261	            hasName ? ((data[i] as DataItem).value = value[0]) : (data[i] = value[0]);
262	        }
263	    }
264	
265	    return {
266	        name: seriesName,
267	        data: data
268	    };
269	}
270	
271	function parseContents(str: string, blockMetaList: SeriesGroupMeta[]) {
272	    const blocks = str.split(new RegExp('\n*' + BLOCK_SPLITER + '\n*', 'g'));
273	    const newOption: ECUnitOption = {
274	        series: []
275	    };
276	    zrUtil.each(blocks, function (block, idx) {
277	        if (isTSVFormat(block)) {
278	            const result = parseTSVContents(block);
279	            const blockMeta = blockMetaList[idx];
280	            const axisKey = blockMeta.axisDim + 'Axis';
281	
282	            if (blockMeta) {
283	                newOption[axisKey] = newOption[axisKey] || [];
284	                (newOption[axisKey] as any)[blockMeta.axisIndex] = {
285	                    data: result.categories
286	                };
287	                newOption.series = (newOption.series as SeriesOption[]).concat(result.series);
288	            }
289	        }
290	        else {
291	            const result = parseListContents(block);
292	            (newOption.series as SeriesOption[]).push(result);
293	        }
294	    });
295	    return newOption;
296	}
