298	export interface ToolboxDataViewFeatureOption extends ToolboxFeatureOption {
299	    readOnly?: boolean
300	
301	    optionToContent?: (option: ECUnitOption) => string | HTMLElement
302	    contentToOption?: (viewMain: HTMLDivElement, oldOption: ECUnitOption) => ECUnitOption
303	
304	    icon?: string
305	    title?: string
306	    lang?: string[]
307	
308	    backgroundColor?: ColorString
309	
310	    textColor?: ColorString
311	    textareaColor?: ColorString
312	    textareaBorderColor?: ColorString
313	
314	    buttonColor?: ColorString
315	    buttonTextColor?: ColorString
316	}
